import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Integrate Files with Your Business","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/attachments","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/attachments.md","filePath":"en/tutorials/attachments.md"}'),o={name:"en/tutorials/attachments.md"};function n(r,e,d,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="integrate-files-with-your-business" tabindex="-1">Integrate Files with Your Business <a class="header-anchor" href="#integrate-files-with-your-business" aria-label="Permalink to &quot;Integrate Files with Your Business&quot;">​</a></h1><p>Goal: add private attachments using Core file lifecycle and the S3 adapter. Start API/PostgreSQL/RustFS through the <a href="./../getting-started/quickstart">quickstart</a> and define resource authorization. Your business owns resource/file associations; Files does not know document or ticket permissions.</p><p>Complete reference: <a href="./library-grants">resource authorization</a>.</p><h2 id="construction-and-public-interfaces" tabindex="-1">Construction and Public Interfaces <a class="header-anchor" href="#construction-and-public-interfaces" aria-label="Permalink to &quot;Construction and Public Interfaces&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer">Files types/service</a> expose <code>FileService::from_settings(storage, limits)</code>; use <code>FileService::new(storage, bucket, policy)</code> for another adapter. <code>UploadInput</code> has <code>file_name / content_type / size / sha256</code>. Validate normalizes MIME/digest and checks budgets; start validates again.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Public method</th><th>Result</th></tr></thead><tbody><tr><td>Register</td><td><code>start(connection, actor_id, input)</code></td><td>Upload with public <code>id</code></td></tr><tr><td>Replay</td><td><code>load(connection, id)</code></td><td>Original Upload</td></tr><tr><td>Sign upload</td><td><code>upload_capability(upload)</code></td><td>URL, method, headers, expires_at</td></tr><tr><td>Plan completion</td><td><code>plan_completion(connection, id)</code></td><td>Ready / Attempt / Expired / Rejected</td></tr><tr><td>Verify</td><td><code>verify_candidate(attempt)</code></td><td>VerifiedCandidate</td></tr><tr><td>Abandon</td><td><code>abandon(connection, attempt, rejected)</code></td><td>Candidate can be reclaimed</td></tr><tr><td>Publish</td><td><code>publish(connection, verified)</code></td><td>Adopted / Existing / Expired</td></tr><tr><td>Download</td><td><code>download(connection, id, inline)</code></td><td>DownloadCapability</td></tr></tbody></table><p>These are call shapes; source contains complete signatures/types. <code>CompletionAttempt / VerifiedCandidate</code> have private fields and must come from the service, never be constructed to bypass verification.</p><p>Complete reference: <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/knowledge/attachments.rs" target="_blank" rel="noreferrer">Knowledge attachments</a>.</p><h2 id="complete-commit-boundaries" tabindex="-1">Complete Commit Boundaries <a class="header-anchor" href="#complete-commit-boundaries" aria-label="Permalink to &quot;Complete Commit Boundaries&quot;">​</a></h2><ol><li>Short transaction A: validate Session, lock current Membership/resource and authorize; claim the idempotent command, start and insert association, complete with upload_id only, commit. Replay checks association and loads the Upload. Sign outside the transaction; do not persist short-lived URLs.</li><li>The client PUTs staging with returned method/headers. Upload success is still invisible in business attachment lists.</li><li>Short transaction B: reauthorize, verify association, plan_completion and commit the candidate record. Ready replay also checks published business association; Expired/Rejected are explicit failures.</li><li>Outside transactions, verify_candidate performs HEAD, source-ETag conditional COPY to a unique candidate and HEAD/full-byte/size/MIME/SHA-256 checks. Candidates cannot be overwritten; images/PDF also undergo signature checks.</li><li>Short transaction C: revalidate current credential, membership, resource/access/association and expiry; publish, publish business association, append Audit and commit. Abandon failed candidates while retaining durable cleanup records.</li></ol><p>Reauthorize after external I/O; initial access does not guarantee publication access. Concurrent completion adopts one ready object and returns the same attachment to others. Audit failure rolls state/association back for recoverable completion. Timeout does not prove the remote write failed; record candidates before I/O.</p><h2 id="downloads-and-configuration" tabindex="-1">Downloads and Configuration <a class="header-anchor" href="#downloads-and-configuration" aria-label="Permalink to &quot;Downloads and Configuration&quot;">​</a></h2><p>Defaults are 20 MiB per file, 900 seconds upload and 60 seconds download; actual values come from the <a href="./../reference/config">configuration reference</a>. Check association/current resource access before signing a ready file. <code>ready_info(connection, ids)</code> reads already-authorized IDs in bulk without doing business authorization.</p><p>Revocation/deletion stops new links; issued URLs may work until expiry and accepted transfers may continue. Store file IDs, not signed URLs. S3 credentials stay in API/Worker and Cookies never go to S3. Separate <code>S3_ENDPOINT</code> and <code>S3_PUBLIC_ENDPOINT</code>; sign the public origin rather than rewriting hostname/path afterward.</p><h2 id="verify-and-recover" tabindex="-1">Verify and Recover <a class="header-anchor" href="#verify-and-recover" aria-label="Permalink to &quot;Verify and Recover&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap-storage</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-storage.mjs</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attachments</span></span></code></pre></div><p>Real HTTP/storage checks cover staging invisibility, unique publication, size/type rejection, Audit rollback, associations and rejection after revocation/Session expiry/resource deletion during copying. Expired/rejected uploads need new resources; transient failures retry the original resource. Preserve these boundaries and register association migrations, Router, tests and ownership. Continue with <a href="./document-exports">generated files and Jobs</a> and <a href="./deletion-cleanup">object cleanup</a>.</p><p>Complete reference: <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/attachments.rs" target="_blank" rel="noreferrer">Real HTTP/storage checks</a>.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/09-attachments.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,22)])])}const b=t(o,[["render",n]]);export{u as __pageData,b as default};
